    reviewed=set(i for s in segs for i in range(s['start'],s['end']+1))
    assert all(i in reviewed for i in range(1,len(lines)+1)),path
    assert all(s['sha256']==sha(p) for s in segs),path
    name=p.name
    assessment=core_roles.get(n,{}).get(name)
    if assessment is None:
        if name=='__init__.py':assessment='Read entire package initializer; no mathematical checker logic is supplied by this namespace marker.'
        elif name=='solver.py':assessment=notes[f'C{n:03}']['assessments'].get('mathematical_core','Exact finite producer')+' Reference output remains untrusted until the reviewed checker conditions hold; see family source issues.'
        elif name=='dual_evaluator.py':assessment='Read dispatch and combination of the two owner checks. Acceptance is conjunction, not a proof that either individual verifier is complete or independent; exceptions remain possible in called validators.'
        elif name=='ddc_tracer.py':assessment='Read trace data structure/export and alphabet checks. A DDC letter labels an operation; it does not prove the operation, scientific meaning, or authority. C011-C014 historical hash/clock behavior and later trace-only exports have different custody ceilings.'
        elif name=='runner.py':assessment='Read entrypoint/import/JSON flow. Runs trusted reference code or public examples directly; the sandbox label supplies no process/network/resource isolation by itself. Not used for model/provider calls in this audit.'
        elif name.startswith('eval_arm'):assessment='Read entire prompt, arm selection and delegated query/run wrapper. Shared evaluator dependency is absent; not executed. Historical metadata checked separately, not promoted to live provider proof.'
        elif name=='test_judge_set_hygiene.py':assessment='Read metadata-stripped payload uniqueness check; distinct bytes/JSON inputs are not distinct isomorphism classes or independent theorem coverage. Dataset dispositions replayed separately.'
